const assert = require('node:assert/strict')
const fs = require('node:fs')
const nodeModule = require('node:module')
const path = require('node:path')
const { performance } = require('node:perf_hooks')
const { fileURLToPath } = require('node:url')
const { isMainThread, threadId } = require('node:worker_threads')

const source = process.env.HMR_WATCH_OBSERVER_SOURCE
const trace = process.env.HMR_WATCH_OBSERVER_TRACE
const runtime = process.env.HMR_WATCH_OBSERVER_RUNTIME
const entry = process.argv[1]?.replaceAll('\\', '/') ?? ''
const role = entry.endsWith('/scripts/benchmark-templates-hmr.ts') ? 'driver'
  : entry.endsWith('/packages/weapp-vite/bin/weapp-vite.js') ? 'cli' : undefined

if (isMainThread && role) {
  assert(source && path.isAbsolute(source), 'Observer source must be absolute')
  assert(trace && path.isAbsolute(trace), 'Observer trace must be absolute')
  assert(runtime && path.isAbsolute(runtime), 'Observer runtime must be absolute')
  const target = path.resolve(source)
  const records = []
  const errors = []
  let sequence = 0
  let operationSequence = 0
  let watcherSequence = 0
  let dropped = 0
  const symbol = Symbol.for('weapp-private-hmr-watch-observer-v1')
  const originalAppend = fs.appendFileSync

  // 只在内存中记录；观测失败不能替换原 I/O、hook 或 CLI 的错误。
  function observe(label, fn) {
    try { return fn() }
    catch (error) { try { errors.push(`${label}: ${String(error)}`) } catch {} }
  }
  function record(event, details = {}) {
    observe(event, () => {
      if (records.length >= 10_000) { dropped++; return }
      records.push({ sequence: ++sequence, atMs: performance.now(), event, ...details })
    })
  }
  function filename(value) {
    if (typeof value === 'string') return path.resolve(value)
    if (Buffer.isBuffer(value)) return path.resolve(value.toString())
    if (value instanceof URL && value.protocol === 'file:') return path.resolve(fileURLToPath(value))
  }
  function isTarget(value) { return observe('file identity', () => filename(value) === target) === true }
  function statSnapshot(stat) {
    return observe('stat snapshot', () => ({ size: stat.size, mtimeMs: stat.mtimeMs, ino: stat.ino }))
  }

  // 包装既有监听器；保持原 StatWatcher、回调参数、this 与取消订阅身份。
  const watchFile = fs.watchFile
  const unwatchFile = fs.unwatchFile
  const listeners = new Map()
  fs.watchFile = function (...args) {
    if (!isTarget(args[0]) || typeof args.at(-1) !== 'function') return watchFile.apply(this, args)
    const listener = args.at(-1)
    const watcher = ++watcherSequence
    const options = typeof args[1] === 'object' && args[1] !== null ? args[1] : {}
    const wrapped = function (current, previous) {
      record('watchFile-callback', { watcher, current: statSnapshot(current), previous: statSnapshot(previous) })
      return listener.apply(this, arguments)
    }
    args[args.length - 1] = wrapped
    record('watchFile-register-begin', { watcher, interval: options.interval, persistent: options.persistent })
    try {
      const result = watchFile.apply(this, args)
      const registered = listeners.get(listener) ?? []
      registered.push({ wrapped, watcher })
      listeners.set(listener, registered)
      record('watchFile-register-end', { watcher })
      return result
    }
    catch (error) { record('watchFile-register-error', { watcher }); throw error }
  }
  fs.unwatchFile = function (...args) {
    if (!isTarget(args[0])) return unwatchFile.apply(this, args)
    const registration = typeof args[1] === 'function' ? listeners.get(args[1])?.at(-1) : undefined
    const removed = args[1] === undefined
      ? [...listeners.values()].flatMap(items => items.map(item => item.watcher))
      : registration ? [registration.watcher] : []
    record('watchFile-unregister-begin', { all: args[1] === undefined, watchers: removed })
    if (typeof args[1] !== 'function') {
      const result = unwatchFile.apply(this, args)
      listeners.clear()
      record('watchFile-unregister-end', { watchers: removed })
      return result
    }
    const registered = listeners.get(args[1])
    if (!registered?.length) {
      const result = unwatchFile.apply(this, args)
      record('watchFile-unregister-end', { watchers: removed })
      return result
    }
    // removeListener 删除同一函数最后一次登记，保持重复 listener 的原有语义。
    const result = unwatchFile.call(this, args[0], registered.at(-1).wrapped)
    registered.pop()
    if (!registered.length) listeners.delete(args[1])
    record('watchFile-unregister-end', { watchers: removed })
    return result
  }
  nodeModule.syncBuiltinESMExports()

  // overlay 仅在已经存在的 await 前后调用；不旁路订阅或替换 Promise。
  assert.equal(globalThis[symbol], undefined, 'Observer symbol already exists')
  globalThis[symbol] = (event, file, details = {}) => {
    if (!isTarget(file)) return
    return observe('hook observation', () => {
      const operation = event === 'save-begin' ? ++operationSequence : details.operation
      record(event, { ...details, ...(operation === undefined ? {} : { operation }) })
      return operation
    })
  }

  record('observer-installed', { role })
  process.on('exit', code => {
    observe('write trace', () => originalAppend.call(fs, trace, JSON.stringify({
      contract: 'private-hmr-watch-observer-v1', pid: process.pid, role, isMainThread, threadId,
      argv: process.argv, code, clock: { timeOrigin: performance.timeOrigin, now: 'performance.now' },
      source: target, runtime: path.resolve(runtime), records, errors, dropped,
    }) + '\n'))
  })
}

