import assert from 'node:assert/strict'
import { execFile } from 'node:child_process'
import { createHash } from 'node:crypto'
import { constants } from 'node:fs'
import { cp, lstat, mkdir, readFile, readdir, readlink, realpath, rm, symlink, writeFile } from 'node:fs/promises'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'
import { promisify } from 'node:util'
import { verifyNextRuntimes } from '../isolate-next-runtimes.mjs'

const self = fileURLToPath(import.meta.url)
const toolRoot = path.dirname(path.dirname(self))
const contract = 'private-hmr-watch-overlay-v1'
const symbol = "Symbol.for('weapp-private-hmr-watch-observer-v1')"
const observer = `(globalThis as any)[${symbol}]?.`
const hash = value => createHash('sha256').update(value).digest('hex')
const posix = value => value.split(path.sep).join('/')
const inside = (root, file) => file === root || file.startsWith(`${root}${path.sep}`)
const sorted = object => Object.fromEntries(Object.entries(object).sort(([a], [b]) => a.localeCompare(b)))
const json = value => `${JSON.stringify(value, null, 2)}\n`
const exists = file => lstat(file).then(() => true, error => { if (error.code === 'ENOENT') return false; throw error })
const tools = ['hmrWatcherObserver/prepareOverlay.mjs', 'hmrWatcherObserver/preload.cjs', 'isolate-next-runtimes.mjs', 'isolate-runtimes.mjs']

async function toolHashes() {
  return Object.fromEntries(await Promise.all(tools.map(async file => [file, hash(await readFile(path.join(toolRoot, file)))])))
}

// 不跟随链接；完整记录依赖和缓存，运行末尾缓存必须由执行层归档并移走。
async function inventory(root, omitMetadata = false) {
  const files = {}, links = {}
  async function walk(directory) {
    for (const entry of (await readdir(directory, { withFileTypes: true })).sort((a, b) => a.name.localeCompare(b.name))) {
      const filename = path.join(directory, entry.name)
      const relative = posix(path.relative(root, filename))
      if (omitMetadata && ['manifest.json', 'links.json'].includes(relative)) continue
      if (entry.isDirectory()) await walk(filename)
      else if (entry.isFile()) files[relative] = hash(await readFile(filename))
      else if (entry.isSymbolicLink()) {
        const target = await realpath(filename)
        assert(inside(root, target), `Link escapes runtime: ${relative}`)
        links[relative] = await readlink(filename)
      }
      else assert.fail(`Unexpected runtime entry: ${relative}`)
    }
  }
  await walk(root)
  const result = { files: sorted(files), links: sorted(links) }
  return { ...result, digest: hash(JSON.stringify(result)) }
}

function replaceOnce(source, before, after, label) {
  assert.equal(source.split(before).length - 1, 1, `Expected one exact injection anchor: ${label}`)
  return source.replace(before, () => after)
}

function instrumentDriver(source) {
  const ready = '      const scenarioResults: ScenarioResult[] = []'
  const measure = `    measure: async (signal) => {
      await update()
      await waitForOutput(marker, absent, signal)
      return performance.now() - startedAt
    },`
  const changes = [
    ['child-preload', '    cliPath,\n    \'dev\',', "    ...(process.env.HMR_WATCH_OBSERVER_PRELOAD ? ['--require', process.env.HMR_WATCH_OBSERVER_PRELOAD] : []),\n    cliPath,\n    'dev',"],
    ['ready', ready, `      for (const scenario of scenarios) {
        ;${observer}('ready', scenario.sourceFile, { scenario: scenario.id, index: -1, phase: 'ready' })
      }
${ready}`],
    ['sample-index', "  let phase = 'prepare'", "  let observerIndex = -1\n  let phase = 'prepare'"],
    ['cycle-index', '      const marker = createMarker(template.id, scenario.id, index)', '      observerIndex = index\n      const marker = createMarker(template.id, scenario.id, index)'],
    ['measurement', measure, `    measure: async (signal) => {
      ;${observer}('write-window-begin', scenario.sourceFile, { scenario: scenario.id, index: observerIndex, phase, marker, absent, startedAt })
      await update()
      await waitForOutput(marker, absent, signal)
      const observedWallMs = performance.now() - startedAt
      ;${observer}('write-window-visible', scenario.sourceFile, { scenario: scenario.id, index: observerIndex, phase, marker, absent, startedAt, wallMs: observedWallMs })
      return observedWallMs
    },`],
  ]
  for (const [label, before, after] of changes) source = replaceOnce(source, before, after, label)
  return { source, injections: changes.map(([label]) => label) }
}

export function instrumentSave(source) {
  const before = `  try {
    await fs.writeFile(temporaryPath, content, 'utf8')
    await renameAtomicFile(temporaryPath, filePath)
  }
  finally {
    await fs.remove(temporaryPath)
  }`
  const after = `  const operation = ${observer}('save-begin', filePath)
  try {
    ;${observer}('temporary-write-begin', filePath, { operation })
    await fs.writeFile(temporaryPath, content, 'utf8')
    ;${observer}('temporary-write-end', filePath, { operation })
    ;${observer}('rename-begin', filePath, { operation })
    await renameAtomicFile(temporaryPath, filePath)
    ;${observer}('rename-end', filePath, { operation })
  }
  catch (error) {
    ;${observer}('save-error', filePath, { operation })
    throw error
  }
  finally {
    ;${observer}('cleanup-begin', filePath, { operation })
    await fs.remove(temporaryPath)
    ;${observer}('cleanup-end', filePath, { operation })
  }
  ;${observer}('save-end', filePath, { operation })`
  return { source: replaceOnce(source, before, after, 'atomic-save'), injections: ['atomic-save'] }
}

function instrumentProvider(source) {
  const before = `\t\tasync hotUpdate({ type, file, read }) {
\t\t\tif (this.environment.name !== "client" || isProfileOutput(file) || ownsExternalWxmlWatch(ctx, file)) return;
\t\t\tif (type === "delete") {
\t\t\t\tonChange({
\t\t\t\t\tevent: type,
\t\t\t\t\tfile
\t\t\t\t});
\t\t\t\treturn;
\t\t\t}
\t\t\ttry {
\t\t\t\tawait read();
\t\t\t} catch (error) {
\t\t\t\tif (error.code === "ENOENT") return;
\t\t\t\tthrow error;
\t\t\t}
\t\t\tonChange({
\t\t\t\tevent: type,
\t\t\t\tfile
\t\t\t});
\t\t}`
  const hook = `globalThis[${symbol}]?.`
  let after = replaceOnce(before, '\t\tasync hotUpdate({ type, file, read }) {', `\t\tasync hotUpdate({ type, file, read }) {\n\t\t\t${hook}("hook-entry", file, { type, environment: this.environment.name });`, 'hook-entry')
  after = replaceOnce(after, '\t\t\t\tawait read();', `\t\t\t\t${hook}("hook-read-begin", file, { type, environment: this.environment.name });\n\t\t\t\tawait read();\n\t\t\t\t${hook}("hook-read-end", file, { type, environment: this.environment.name });`, 'hook-read')
  after = replaceOnce(after, '\t\t\t} catch (error) {', `\t\t\t} catch (error) {\n\t\t\t\t${hook}("hook-read-error", file, { type, environment: this.environment.name });`, 'hook-error')
  return { source: replaceOnce(source, before, after, 'provider-hot-update'), injections: ['hook-entry', 'hook-read', 'hook-error'] }
}

async function assertAncestors(root) {
  for (let ancestor = path.dirname(root); ; ancestor = path.dirname(ancestor)) {
    assert(!await exists(path.join(ancestor, 'node_modules')), `Ancestor exposes unrelated modules: ${ancestor}`)
    if (ancestor === path.dirname(ancestor)) break
  }
}

/** 克隆冻结运行时并注入私有观察点；不运行构建、基准或新的 watcher。 */
export async function prepareOverlay(identityDirectory, destination) {
  identityDirectory = await realpath(identityDirectory)
  const identityFile = path.join(identityDirectory, 'identity.json')
  const identityBytes = await readFile(identityFile)
  const identity = JSON.parse(identityBytes)
  await verifyNextRuntimes(identityDirectory)
  const originalParent = await realpath(identity.runtimeParent)
  assert.equal(originalParent, identity.runtimeParent, 'Identity runtime parent must be canonical')
  destination = path.resolve(destination)
  assert(!await exists(destination), 'Diagnostic parent must be a new directory')
  const diagnosticParent = path.join(await realpath(path.dirname(destination)), path.basename(destination))
  assert(!inside(originalParent, diagnosticParent) && !inside(diagnosticParent, originalParent), 'Runtime roots must be disjoint')
  await assertAncestors(diagnosticParent)
  const originalTree = await inventory(originalParent)
  const toolsBefore = await toolHashes()
  const variants = {}
  const prepared = []
  for (const name of ['baseline', 'candidate']) {
    const variant = identity.variants[name]
    assert.equal(variant.root, path.join(originalParent, name), `Unexpected variant root: ${name}`)
    const providers = Object.keys(variant.files).filter(file => /^packages\/weapp-vite\/dist\/devProvider-[^/]+\.mjs$/.test(file))
    assert.equal(providers.length, 1, `Expected one provider artifact: ${name}`)
    const changed = []
    for (const [file, transform] of [['scripts/benchmark-templates-hmr.ts', instrumentDriver], ['e2e/utils/hmr-helpers.ts', instrumentSave], [providers[0], instrumentProvider]]) {
      const filename = path.join(variant.root, file)
      assert((await lstat(filename)).isFile(), `Injection target must be a regular file: ${name}/${file}`)
      assert.equal(await realpath(filename), filename, `Injection target has a symlink ancestor: ${name}/${file}`)
      const bytes = await readFile(filename)
      const before = hash(bytes)
      assert.equal(before, variant.files[file], `Original injection target changed: ${name}/${file}`)
      const result = transform(bytes.toString('utf8'))
      const after = hash(result.source)
      changed.push({ file, before, after, injections: result.injections })
      prepared.push({ name, file, source: result.source, before, after })
    }
    const files = { ...variant.files, ...Object.fromEntries(changed.map(item => [item.file, item.after])) }
    variants[name] = { root: path.join(diagnosticParent, name), originalRoot: variant.root, files, digest: hash(JSON.stringify(files)), changed }
  }
  await mkdir(diagnosticParent)
  if (process.platform === 'darwin') await promisify(execFile)('/bin/cp', ['-cR', `${originalParent}/.`, diagnosticParent])
  else await cp(originalParent, diagnosticParent, { recursive: true, force: false, errorOnExist: true, verbatimSymlinks: true, mode: constants.COPYFILE_FICLONE_FORCE })
  const remappings = []
  for (const [relative, original] of Object.entries(originalTree.links)) {
    const filename = path.join(diagnosticParent, relative)
    assert.equal(await readlink(filename), original, `Clone changed link bytes: ${relative}`)
    const absolute = path.isAbsolute(original)
    const target = path.resolve(path.dirname(path.join(originalParent, relative)), original)
    assert(inside(originalParent, target), `Lexical link target escapes original runtime: ${relative}`)
    const derived = absolute ? path.relative(path.dirname(filename), path.join(diagnosticParent, path.relative(originalParent, target))) : original
    if (absolute) {
      const kind = (await lstat(await realpath(path.join(originalParent, relative)))).isDirectory() ? 'dir' : 'file'
      await rm(filename)
      await symlink(derived, filename, process.platform === 'win32' ? kind : undefined)
    }
    remappings.push({ file: relative, original, derived, relocated: absolute })
  }
  const clonedTree = await inventory(diagnosticParent)
  assert.deepEqual(clonedTree.files, originalTree.files, 'Clone changed file contents')
  assert.deepEqual(clonedTree.links, sorted(Object.fromEntries(remappings.map(item => [item.file, item.derived]))), 'Clone link map differs')
  for (const item of prepared) {
    const filename = path.join(variants[item.name].root, item.file)
    assert.equal(await realpath(filename), filename, 'Refuse writing through a symlink')
    assert.equal(hash(await readFile(filename)), item.before, 'Cloned injection target changed')
    const currentStat = await lstat(filename)
    const originalStat = await lstat(path.join(identity.variants[item.name].root, item.file))
    assert(currentStat.dev !== originalStat.dev || currentStat.ino !== originalStat.ino, 'Clone must not hardlink mutable files')
    await writeFile(filename, item.source)
  }
  const owner = { tool: contract, diagnosticOnly: true, created: new Date().toISOString(), originalParent, diagnosticParent, identityDirectory, identitySha256: hash(identityBytes) }
  await rm(path.join(diagnosticParent, 'OWNED.json'))
  await writeFile(path.join(diagnosticParent, 'OWNED.json'), json(owner), { flag: 'wx' })
  const links = { mapping: { originalParent, diagnosticParent }, remappings, originalDigest: hash(JSON.stringify(originalTree.links)), derivedDigest: hash(JSON.stringify(clonedTree.links)) }
  const linksBytes = json(links)
  await writeFile(path.join(diagnosticParent, 'links.json'), linksBytes, { flag: 'wx' })
  const tree = await inventory(diagnosticParent, true)
  const expectedFiles = { ...originalTree.files, 'OWNED.json': hash(json(owner)), ...Object.fromEntries(prepared.map(item => [`${item.name}/${item.file}`, item.after])) }
  assert.deepEqual(tree.files, sorted(expectedFiles), 'Undeclared diagnostic file change')
  assert.deepEqual(tree.links, clonedTree.links, 'Diagnostic links changed during injection')
  assert.equal(hash(await readFile(identityFile)), owner.identitySha256, 'Original identity changed')
  await verifyNextRuntimes(identityDirectory)
  assert.deepEqual(await inventory(originalParent), originalTree, 'Original runtime changed')
  assert.deepEqual(await toolHashes(), toolsBefore, 'Overlay tools changed during preparation')
  const manifest = {
    contract, diagnosticOnly: true, created: owner.created,
    original: { identityDirectory, identitySha256: owner.identitySha256, identity, tree: originalTree },
    mapping: { originalParent, diagnosticParent }, variants, tools: toolsBefore,
    links: { file: 'links.json', sha256: hash(linksBytes), originalDigest: links.originalDigest, derivedDigest: links.derivedDigest }, tree,
    cloneMode: process.platform === 'darwin' ? 'cp -cR (clonefile)' : 'COPYFILE_FICLONE_FORCE',
    limitations: ['Diagnostic only: observer overhead cannot establish a Rust speedup.', 'No waits, polling interval changes, new watchers or Promise wrappers.', 'Instrumented provider retains its original source map; injected coordinates are not production source-map evidence.'],
  }
  await writeFile(path.join(diagnosticParent, 'manifest.json'), json(manifest), { flag: 'wx' })
  return { diagnosticParent, manifest: path.join(diagnosticParent, 'manifest.json'), manifestSha256: hash(json(manifest)), variants }
}

/** 运行首尾核对派生树、链接、工具和原冻结样本；缓存须先由执行层归档。 */
export async function verifyOverlay(diagnosticParent) {
  diagnosticParent = await realpath(diagnosticParent)
  const manifestBytes = await readFile(path.join(diagnosticParent, 'manifest.json'))
  const manifest = JSON.parse(manifestBytes)
  assert.equal(manifest.contract, contract)
  assert.equal(manifest.diagnosticOnly, true)
  assert.equal(manifest.mapping.diagnosticParent, diagnosticParent)
  await assertAncestors(diagnosticParent)
  assert.deepEqual(await toolHashes(), manifest.tools, 'Overlay tools changed')
  assert.equal(hash(await readFile(path.join(diagnosticParent, 'links.json'))), manifest.links.sha256, 'Link provenance changed')
  assert.deepEqual(await inventory(diagnosticParent, true), manifest.tree, 'Diagnostic runtime changed')
  const identityFile = path.join(manifest.original.identityDirectory, 'identity.json')
  assert.equal(hash(await readFile(identityFile)), manifest.original.identitySha256, 'Original identity changed')
  await verifyNextRuntimes(manifest.original.identityDirectory)
  assert.deepEqual(await inventory(manifest.mapping.originalParent), manifest.original.tree, 'Original runtime changed')
  return { verified: true, diagnosticOnly: true, diagnosticParent, manifestSha256: hash(manifestBytes), variants: Object.fromEntries(Object.entries(manifest.variants).map(([name, variant]) => [name, { root: variant.root, digest: variant.digest }])) }
}

if (process.argv[1] && path.resolve(process.argv[1]) === self) {
  const args = process.argv.slice(2)
  assert.equal(args.length, 2, 'Usage: node prepareOverlay.mjs <identity-directory> <fresh-diagnostic-parent> | verify <diagnostic-parent>')
  console.log(JSON.stringify(args[0] === 'verify' ? await verifyOverlay(args[1]) : await prepareOverlay(args[0], args[1]), null, 2))
}

