import type { Input, Options, Run, Side } from '../../../../scripts/benchmarkNativeAnalysis/contract.ts'
import assert from 'node:assert/strict'
import { copyFile, mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'
import process from 'node:process'
import { normalizeRoots, warningEvidence } from '../../../../scripts/benchmarkNativeAnalysis/artifacts.ts'
import { hmrEnvironment, parseHmrEvidence } from '../../../../scripts/benchmarkNativeAnalysis/hmr.ts'
import { stageInput } from '../../../../scripts/benchmarkNativeAnalysis/stage.ts'
import { runCollector } from '../../../../scripts/performanceGate/process.ts'

/** 保持正式输入和采样顺序，仅开启真实 HMR 阶段归因；不用于通过性能门禁。 */
export async function collectRun(options: Options, input: Input, kind: Run['kind'], side: Side, pair: number, batch: Run['batch']): Promise<Run> {
  assert(kind === 'hmr' && side === 'off')
  const directory = path.join(options.output, batch, kind, input.id, String(pair), side)
  const result: Run = { input: input.id, kind, side, pair, batch, marker: `native-${batch}-${pair}`, samples: [], native: { calls: 0, failures: 0, processes: 0 } }
  await mkdir(directory, { recursive: true })
  try {
    const staged = await stageInput(options, input)
    result.inputDigest = staged.inputDigest
    result.sourceDigest = staged.sourceDigest
    await writeFile(path.join(directory, 'input-manifest.json'), JSON.stringify(staged.manifest))
    const workspace = path.join(options.output, '.workspace/hmr')
    const preload = process.env.HMR_WATCH_OBSERVER_PRELOAD
    assert(preload && path.isAbsolute(preload))
    const source = path.join(workspace, input.id, 'src/pages/index', input.id === 'weapp-vite-template' ? 'index.ts' : 'index.vue')
    const trace = path.join(directory, 'watch-observer.jsonl')
    await runCollector(process.execPath, ['--require', preload, '--import', 'tsx', 'scripts/benchmark-templates-hmr.ts'], {
      cwd: options.root,
      logFile: path.join(directory, 'collector.log'),
      timeoutMs: 15 * 60_000,
      env: { ...hmrEnvironment(options, input, result, staged.project, directory, workspace), TEMPLATES_HMR_PROFILE: '1', HMR_WATCH_OBSERVER_PRELOAD: preload, HMR_WATCH_OBSERVER_SOURCE: source, HMR_WATCH_OBSERVER_TRACE: trace, HMR_WATCH_OBSERVER_RUNTIME: options.root },
      redact: [staged.project, options.root, options.output],
    })
    const report = JSON.parse(await readFile(path.join(directory, 'report.json'), 'utf8')) as unknown
    const log = await readFile(path.join(directory, 'logs', `${input.id}.dev.log`), 'utf8')
    parseHmrEvidence(report, input, result, staged.inputDigest, warningEvidence(log, [workspace, staged.project, options.root]))
    await copyFile(path.join(workspace, input.id, '.weapp-vite/hmr-profile.jsonl'), path.join(directory, 'profile.raw.jsonl'))
  }
  catch (error) {
    result.error = normalizeRoots(String(error), [options.output, options.root])
  }
  finally {
    await rm(path.join(options.output, '.workspace'), { recursive: true, force: true })
    await writeFile(path.join(directory, 'sample.json'), JSON.stringify(result))
  }
  return result
}

