import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'
import { INPUTS } from '../../../../scripts/benchmarkNativeAnalysis/contract.ts'
import { captureIdentity } from '../../../../scripts/benchmarkNativeAnalysis/stage.ts'
import { runCollector } from '../../../../scripts/performanceGate/process.ts'
import { verifyOverlay } from './prepareOverlay.mjs'

const [directory, destination] = process.argv.slice(2)
assert(directory && destination)
const diagnosticParent = path.resolve(directory)
const output = path.resolve(destination)
assert(!output.startsWith(diagnosticParent + path.sep) && output !== diagnosticParent)
const manifestFile = path.join(diagnosticParent, 'manifest.json')
const manifestBytes = await readFile(manifestFile)
const manifest = JSON.parse(manifestBytes.toString())
assert.equal(manifest.contract, 'private-hmr-watch-overlay-v1')
assert.equal(manifest.diagnosticOnly, true)
await mkdir(output)
const sha256 = value => createHash('sha256').update(value).digest('hex')
const base = fileURLToPath(new URL('.', import.meta.url))
const preload = path.join(base, 'preload.cjs')
const collector = path.join(base, 'worker.mts')
const cachePolicy = {
  contract: 'isolated-collect-cache-policy-v2',
  rolldownCaches: { names: ['.rolldown-require', '.rolldown-require-cache'], policy: 'absent-before-prepare; first-repeat-share; archive-owned-directory-after-collectRun' },
  inputCaches: { names: ['.vite', '.vite-temp'], location: 'input.dependencies/node_modules', policy: 'absent-before-prepare; first-repeat-share; archive-owned-directory-after-collectRun' },
}
const report = {
  contract: 'hmr-watch-boundary-diagnostic-v1',
  interpretation: 'Four paired runs of each of two HMR groups; unchanged polling interval, save mode and cycles. Instrumented timing is attribution only, not acceptance or Rust gain.',
  manifestFile, manifestSha256: sha256(manifestBytes), started: new Date().toISOString(), completed: null,
  pairs: 4, output, cachePolicy, runs: [], identityBefore: null, identityAfter: null, error: null,
  tools: Object.fromEntries(await Promise.all(['preload.cjs', 'worker.mts', 'collect.mts', 'compare.mts', 'prepareOverlay.mjs'].map(async name => [name, sha256(await readFile(path.join(base, name)))]))),
}
const controller = new AbortController()
const stop = () => controller.abort()
process.once('SIGINT', stop)
process.once('SIGTERM', stop)
const persist = () => writeFile(path.join(output, 'report.json'), JSON.stringify(report, null, 2))
const inputs = INPUTS.filter(input => ['weapp-vite-template', 'weapp-vite-wevu-template'].includes(input.id))
try {
  report.identityBefore = await verifyOverlay(diagnosticParent)
  const options = {}
  for (const variant of ['baseline', 'candidate']) {
    const root = manifest.variants[variant].root
    options[variant] = { root, output, nativePath: path.join(root, 'packages/ast-native/index.js'), mode: 'smoke', runtime: 'classic', buildPairs: 4, hmrPairs: 4, inputIdentities: {} }
    options[variant].inputIdentities = await captureIdentity(options[variant])
  }
  await persist()
  for (let pair = 0; pair < 4; pair++) for (const input of inputs) {
    for (const variant of pair % 2 ? ['candidate', 'baseline'] : ['baseline', 'candidate']) {
      assert(!controller.signal.aborted, 'Interrupted before next side')
      const label = `${pair}-${input.id}-${variant}`
      const taskFile = path.join(output, 'orchestration', `${label}.task.json`)
      const resultFile = path.join(output, 'orchestration', `${label}.result.json`)
      const observationFile = path.join(output, 'orchestration', `${label}.cache.json`)
      const temporaryDirectory = path.join(output, 'temporary', 'primary', String(pair), 'hmr', input.id, variant)
      await mkdir(path.dirname(taskFile), { recursive: true })
      await mkdir(path.dirname(temporaryDirectory), { recursive: true })
      await mkdir(temporaryDirectory)
      await writeFile(taskFile, JSON.stringify({ options: options[variant], input, stage: 'hmr', native: 'off', variant, pair, batch: 'primary', resultFile, observationFile, temporaryDirectory, cachePolicy }), { flag: 'wx' })
      console.log(`watch-observer pair=${pair + 1}/4 ${input.id} ${variant}`)
      await runCollector(process.execPath, ['--import', 'tsx', collector, taskFile], {
        cwd: process.cwd(), logFile: path.join(output, 'orchestration', `${label}.log`), timeoutMs: 20 * 60_000,
        env: { NODE_OPTIONS: '', NODE_PATH: '', NODE_COMPILE_CACHE: undefined, NODE_DISABLE_COMPILE_CACHE: undefined, TSX_DISABLE_CACHE: '1', NATIVE_BENCHMARK_SOURCE_ROOTS: '1', TMPDIR: temporaryDirectory, TMP: temporaryDirectory, TEMP: temporaryDirectory, HMR_WATCH_OBSERVER_PRELOAD: preload },
        redact: [diagnosticParent, process.cwd()],
      })
      const run = JSON.parse(await readFile(resultFile, 'utf8'))
      const before = path.join(output, 'primary/hmr', input.id, String(pair), 'off')
      const retained = path.join(output, 'primary/hmr', input.id, String(pair), variant)
      await rename(before, retained)
      const cacheObservation = JSON.parse(await readFile(observationFile, 'utf8'))
      const traceFile = path.join(retained, 'watch-observer.jsonl')
      const trace = (await readFile(traceFile, 'utf8')).trim().split('\n').map(line => JSON.parse(line))
      report.runs.push({ pair, input: input.id, variant, run, trace, traceSha256: sha256(await readFile(traceFile)), cacheObservation })
      await persist()
      assert(!run.error, run.error)
      assert.equal(run.samples.length, 12)
      assert.equal(trace.length, 2)
      assert.deepEqual(trace.map(row => row.role).sort(), ['cli', 'driver'])
      assert.equal(new Set(trace.map(row => row.pid)).size, 2)
      const source = path.join(output, '.workspace/hmr', input.id, 'src/pages/index', input.id === 'weapp-vite-template' ? 'index.ts' : 'index.vue')
      for (const row of trace) {
        assert.equal(row.code, row.role === 'cli' ? 143 : 0, 'CLI uses the existing managed SIGTERM teardown; driver must succeed')
        assert.equal(row.isMainThread, true)
        assert.equal(row.threadId, 0)
        assert.equal(row.source, source)
        assert.equal(row.runtime, options[variant].root)
        assert.deepEqual(row.errors, [])
        assert.equal(row.dropped, 0)
      }
      const cli = trace.find(row => row.role === 'cli')
      const registrations = cli.records.filter(event => event.event === 'watchFile-register-begin')
      assert(registrations.length > 0)
      assert(registrations.every(event => event.interval === 120))
      const unregistered = new Set(cli.records.filter(event => event.event === 'watchFile-unregister-end').flatMap(event => event.watchers))
      assert(registrations.every(event => unregistered.has(event.watcher)), 'Every target watcher must be released by existing teardown')
      assert.equal(cacheObservation.beforePrepare.temporaryDirectoryEmpty, true)
      assert.equal(cacheObservation.beforePrepare.npmCacheAbsent, true)
      assert(!cacheObservation.error)
    }
  }
  for (let pair = 0; pair < 4; pair++) for (const input of inputs) {
    const a = report.runs.find(row => row.pair === pair && row.input === input.id && row.variant === 'baseline').run
    const b = report.runs.find(row => row.pair === pair && row.input === input.id && row.variant === 'candidate').run
    for (let index = 0; index < 12; index++) {
      assert.equal(a.samples[index].id, b.samples[index].id)
      assert.deepEqual(a.samples[index].output, b.samples[index].output)
      assert.deepEqual(a.samples[index].warnings, b.samples[index].warnings)
      assert.equal(a.samples[index].inputDigest, b.samples[index].inputDigest)
    }
  }
  assert.equal(sha256(await readFile(manifestFile)), report.manifestSha256)
  for (const [name, digest] of Object.entries(report.tools)) assert.equal(sha256(await readFile(path.join(base, name))), digest, 'Observer collector changed')
  report.identityAfter = await verifyOverlay(diagnosticParent)
}
catch (error) { report.error = String(error); process.exitCode = 1 }
finally {
  process.off('SIGINT', stop)
  process.off('SIGTERM', stop)
  report.completed = new Date().toISOString()
  await persist()
}
console.log(JSON.stringify({ output, runs: report.runs.length, error: report.error }, null, 2))

