import assert from 'node:assert/strict'
import { readFile, writeFile } from 'node:fs/promises'
import path from 'node:path'
import process from 'node:process'

const [reportFile, destination] = process.argv.slice(2)
assert(reportFile && destination)
const report = JSON.parse(await readFile(reportFile, 'utf8'))
assert.equal(report.contract, 'hmr-watch-boundary-diagnostic-v1')
assert.equal(report.error, null)
assert.equal(report.runs.length, 16)
assert(report.identityBefore.verified && report.identityAfter.verified)
const rows = []
const issues = []
for (const run of report.runs) {
  const driver = run.trace.find(row => row.role === 'driver')
  const cli = run.trace.find(row => row.role === 'cli')
  for (const trace of [driver, cli]) {
    assert(Number.isFinite(trace.clock.timeOrigin))
    trace.records.forEach((record, index) => {
      assert.equal(record.sequence, index + 1)
      assert(Number.isFinite(record.atMs) && record.atMs >= 0)
      if (index) assert(record.atMs >= trace.records[index - 1].atMs)
    })
  }
  const epoch = (row, record) => row.clock.timeOrigin + record.atMs
  const begin = driver.records.filter(record => record.event === 'write-window-begin')
  const expected = run.input === 'weapp-vite-template' ? 4 : 12
  assert.equal(begin.length, expected)
  assert.equal(driver.records.filter(record => record.event === 'write-window-visible').length, expected)
  const usedCallbacks = new Set()
  const retained = path.join(report.output, 'primary/hmr', run.input, String(run.pair), run.variant)
  const detail = JSON.parse(await readFile(path.join(retained, 'report.json'), 'utf8'))
  for (const window of begin) {
    const visible = driver.records.filter(record => record.event === 'write-window-visible' && record.scenario === window.scenario && record.index === window.index && record.phase === window.phase)
    assert.equal(visible.length, 1)
    const end = visible[0]
    const saves = driver.records.filter(record => record.event === 'save-begin' && record.sequence > window.sequence && record.sequence < end.sequence)
    assert.equal(saves.length, 1)
    const operation = saves[0].operation
    const events = driver.records.filter(record => record.operation === operation)
    const names = ['save-begin', 'temporary-write-begin', 'temporary-write-end', 'rename-begin', 'rename-end', 'cleanup-begin', 'cleanup-end', 'save-end']
    assert.deepEqual(events.map(record => record.event), names)
    const renameBegin = epoch(driver, events[3])
    const renameEnd = epoch(driver, events[4])
    const visibleAt = epoch(driver, end)
    const callbacks = cli.records.filter(record => record.event === 'watchFile-callback' && epoch(cli, record) >= renameBegin && epoch(cli, record) <= visibleAt)
