import assert from 'node:assert/strict'
import { execFile } from 'node:child_process'
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises'
import os from 'node:os'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'
import { promisify } from 'node:util'
import { instrumentSave } from './prepareOverlay.mjs'

const execute = promisify(execFile)
const sourceFile = fileURLToPath(new URL('../../../../e2e/utils/hmr-helpers.ts', import.meta.url))
const source = await readFile(sourceFile, 'utf8')
const patched = instrumentSave(source).source
const anchor = 'export async function replaceFileByRename('
assert.equal(patched.split(anchor).length, 2)
const fixedFunction = patched.slice(patched.indexOf(anchor)).trim()
assert(fixedFunction.endsWith('}'))
const brokenFunction = fixedFunction.replace(/^(\s*);(\(globalThis as any\))/gm, '$1$2')
assert.notEqual(brokenFunction, fixedFunction)
const temporary = await mkdtemp(path.join(os.tmpdir(), 'hmr-observer-save-check-'))

function fixture(functionSource, broken) {
  return `
import assert from 'node:assert/strict'
import path from 'node:path'
const symbol = Symbol.for('weapp-private-hmr-watch-observer-v1')
let calls: string[] = [], events: string[] = [], failures: Record<string, Error> = {}
const randomUUID = () => 'controlled-save-id'
const fs = {
  async writeFile(...args: unknown[]) { calls.push('write'); if (failures.write) throw failures.write; return { deliberatelyNotCallable: true } },
  async remove(...args: unknown[]) { calls.push('remove'); if (failures.remove) throw failures.remove; return { deliberatelyNotCallable: true } },
}
async function renameAtomicFile(...args: unknown[]) { calls.push('rename'); if (failures.rename) throw failures.rename; return { deliberatelyNotCallable: true } }
${functionSource}
const cases = ${JSON.stringify(broken ? [{ name: 'old-ASI-regression', fail: [], observer: true }] : [
    { name: 'success', fail: [], observer: true },
    { name: 'observer-absent', fail: [], observer: false },
    { name: 'write-error', fail: ['write'], observer: true },
    { name: 'rename-error', fail: ['rename'], observer: true },
    { name: 'cleanup-error', fail: ['remove'], observer: true },
    { name: 'cleanup-over-write-error', fail: ['write', 'remove'], observer: true },
    { name: 'cleanup-over-rename-error', fail: ['rename', 'remove'], observer: true },
  ])}
for (const testcase of cases) {
  calls = []; events = []; failures = Object.fromEntries(testcase.fail.map(step => [step, new Error(step)]))
  if (testcase.observer) (globalThis as any)[symbol] = (event: string) => { events.push(event); return event === 'save-begin' ? 1 : undefined }
  else delete (globalThis as any)[symbol]
  if (${broken}) {
    await assert.rejects(replaceFileByRename('fixture.vue', 'complete content'), error => error instanceof TypeError && /not a function/.test(error.message))
    assert.deepEqual(calls, ['write', 'remove'])
  } else {
    const expectedError = failures.remove ?? failures.write ?? failures.rename
    if (expectedError) await assert.rejects(replaceFileByRename('fixture.vue', 'complete content'), error => error === expectedError)
    else await replaceFileByRename('fixture.vue', 'complete content')
    assert.deepEqual(calls, failures.write ? ['write', 'remove'] : ['write', 'rename', 'remove'])
    assert.equal(calls.filter(step => step === 'write').length, 1)
    assert.equal(calls.filter(step => step === 'remove').length, 1)
    assert.equal(calls.filter(step => step === 'rename').length, failures.write ? 0 : 1)
    if (testcase.observer && !expectedError) assert.deepEqual(events, ['save-begin', 'temporary-write-begin', 'temporary-write-end', 'rename-begin', 'rename-end', 'cleanup-begin', 'cleanup-end', 'save-end'])
    if (!testcase.observer) assert.deepEqual(events, [])
  }
}
delete (globalThis as any)[symbol]
console.log(JSON.stringify({ broken: ${broken}, cases: cases.map(item => item.name), status: 'passed' }))
`
}

try {
  await writeFile(path.join(temporary, 'package.json'), '{"type":"module"}')
  const results = []
  for (const broken of [true, false]) {
    const file = path.join(temporary, broken ? 'broken.ts' : 'fixed.ts')
    await writeFile(file, fixture(broken ? brokenFunction : fixedFunction, broken))
    const result = await execute(process.execPath, ['--import', 'tsx', file], {
      cwd: process.cwd(), env: { ...process.env, NODE_OPTIONS: '', TSX_DISABLE_CACHE: '1' }, timeout: 10_000,
    })
    results.push(JSON.parse(result.stdout.trim()))
  }
  console.log(JSON.stringify({ transpiler: 'actual tsx loader', results }))
}
finally {
  await rm(temporary, { recursive: true, force: true })
}
